"""Protect a fixed twelve-coordinate positional probe family on256 output rows.

The five sinusoidal periods are8,16,32,64,128. Linear/quadratic position are
also exact frozen-embedding constraints. No numeric-token or sum labels enter.
"""
from pathlib import Path
import math,json,torch
ROOT=Path(__file__).resolve().parents[1];torch.set_num_threads(6);torch.set_grad_enabled(False);h=torch.load(ROOT/'host/ckpt.pt',weights_only=True,mmap=True)['model'];d=torch.load(ROOT/'artifacts/n_host_calib0.pt',weights_only=True,mmap=True);E=h['transformer.wte.weight'].double();wp=h['transformer.wpe.weight'][:64].double();A=(d['captures']['0.raw'].double()-E[d['inputs']]-wp[None,:,:]).reshape(-1,768);mean=A.mean(0);Ct=E.T@E/len(E);Ca=A.T@A/len(A);C=Ct+Ca;C.diagonal().add_(float(C.trace()/768)*1e-7);t=torch.arange(64,dtype=torch.float64);periods=[8,16,32,64,128];target=torch.stack([f(t*2*math.pi/p) for p in periods for f in (torch.cos,torch.sin)]+[t/64,(t/64).square()],1);D=torch.cat((wp,torch.ones(1,768,dtype=torch.float64)));T=torch.cat((target,torch.zeros(1,12,dtype=torch.float64)));inv=torch.linalg.solve(C,D.T);full=inv@torch.linalg.solve(D@inv,T);Q,_=torch.linalg.qr(full,mode='reduced');support=Q.square().sum(1).argsort(descending=True)[:256];Ds=D[:,support];Cs=C[support][:,support];iv=torch.linalg.solve(Cs,Ds.T);R=torch.zeros(768,12,dtype=torch.float64);R[support]=iv@torch.linalg.solve(Ds@iv,T);H,_=torch.linalg.qr(R,mode='reduced');report={'support_rows':256,'fields':12,'periods':periods,'constraint_error':float((D@R-T).abs().max()),'token_coordinate_rms':torch.diag(R.T@Ct@R).sqrt().tolist(),'native_attention_energy_fraction_removed':float(torch.trace(H.T@Ca@H)/Ca.trace()),'readout_norms':R.norm(dim=0).tolist()};out={'readouts':R,'frame':H,'support':support,'attention_mean':mean,'position_targets':target,'fields':[f'{kind}{p}' for p in periods for kind in ('cos','sin')]+['u','u2'],'report':report};torch.save(out,ROOT/'artifacts/s_position_coordinates_v2.pt');(ROOT/'artifacts/s_position_coordinates_v2.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2))
